// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address bankCaller) public {
        vm.assume(bankCaller != address(0));

        vm.prank(bankCaller);
        BankHelper bank = new BankHelper();

        bool ok;
        vm.prank(address(bank));
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.tokenBalance(address(bank)) == 20);
    }
}

contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
